import type { SVGProps } from 'react';
import paths from './brand-paths.json';

type BrandSvgProps = Omit<SVGProps<SVGSVGElement>, 'viewBox' | 'children'> & {
  /** Accessible name. Pass `null` when adjacent text already names the brand. */
  title?: string | null;
};

/** The VYSEL wordmark. Inherits `color` (currentColor). Path data generated by scripts/build-brand-assets.mjs. */
export function Wordmark({ title = 'VYSEL', ...rest }: BrandSvgProps) {
  return (
    <svg viewBox={paths.wordmark.viewBox} fill="currentColor" role={title ? 'img' : undefined} aria-label={title ?? undefined} aria-hidden={title ? undefined : true} {...rest}>
      <path d={paths.wordmark.d} />
    </svg>
  );
}

/** V monogram with the rose-gold facet. For avatars, loaders, app chrome. */
export function Monogram({ title = 'VYSEL', ...rest }: BrandSvgProps) {
  return (
    <svg viewBox={paths.monogram.viewBox} role={title ? 'img' : undefined} aria-label={title ?? undefined} aria-hidden={title ? undefined : true} {...rest}>
      <path fill="currentColor" d={paths.monogram.d} />
      <path fill="rgb(var(--vy-rose-gold-500))" d={paths.monogram.facet} />
    </svg>
  );
}
